"""Persist host-authored copilot messages to the Copilot v2 thread.

Hello's jobs write chat messages no copilot turn produced — the generation
prompt, the template prompt, the welcome message, the training-success and
rollback messages — and persisted them only to the v1 history store, so v2
dropped all of them on reload. Called from the two v1 persistence entry points in
:mod:`rasa.builder.copilot.history_store` rather than from each job, which also
keeps the rows in the order they happened: the store is append-only, so a later
backfill could not reorder them.

Host-side by construction, and deletable with the v1 store it shadows (S15). The
runtime package only supplies the row shapes.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Optional

import structlog

# Read through the module, not by value: COPILOT_HISTORY_SQLITE_PATH has to
# resolve to the same file the v1 store and the route layer use.
from rasa.builder import config as builder_config
from rasa.builder.copilot.constants import (
    DEFAULT_COPILOT_CHAT_ID,
    ROLE_ASSISTANT,
    ROLE_USER,
)
from rasa.builder.copilot.models import ResponseCategory

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.thread_store import SQLiteThreadStore

structlogger = structlog.get_logger()

# Must match the frontend, which reads history under `thread-${projectId}`
# (frontend/src/api/copilot/v2.ts) using the id project-service injects here as
# HELLO_RASA_PROJECT_ID. Disagree and these rows land in a thread nobody reads.
_THREAD_ID_PREFIX = "thread-"


def copilot_v2_thread_id() -> Optional[str]:
    """Return this project's v2 thread id, or ``None`` when it is unknowable.

    Unknowable without ``HELLO_RASA_PROJECT_ID`` — a local run, where the
    frontend falls back to an id derived from the project URL instead.
    """
    project_id = (builder_config.HELLO_RASA_PROJECT_ID or "").strip()
    if not project_id:
        return None
    return f"{_THREAD_ID_PREFIX}{project_id}"


def open_copilot_v2_thread_store() -> "SQLiteThreadStore":
    """Open the v2 thread store for the configured database.

    The lazy import keeps the copilot-v2 extra optional for hosts running v1
    only. Callers on a hot path should hold on to the result.
    """
    from rasa.builder.copilot.pydantic_ai.thread_store import SQLiteThreadStore

    return SQLiteThreadStore(builder_config.COPILOT_HISTORY_SQLITE_PATH)


async def persist_user_message_to_v2_thread(text: str, chat_id: Optional[str]) -> None:
    """Append a host-authored user message to the v2 thread."""
    if not text or not _should_persist(chat_id):
        return

    await _append(text, role=ROLE_USER)


async def persist_copilot_message_to_v2_thread(
    text: str,
    chat_id: Optional[str],
    response_category: ResponseCategory = ResponseCategory.COPILOT,
) -> None:
    """Append a host-authored copilot message to the v2 thread.

    Skips a message with no text — a bare commit or log block — since v2 rows
    hold text only and there would be nothing left to render.
    """
    if not text or not _should_persist(chat_id):
        return

    await _append(text, role=ROLE_ASSISTANT, response_category=response_category)


def _should_persist(chat_id: Optional[str]) -> bool:
    """Whether a message persisted under ``chat_id`` belongs in the v2 thread.

    Only the default chat: v2 keys one thread per project, so writing a
    secondary v1 chat into it would merge two conversations into one transcript.
    """
    if not builder_config.COPILOT_V2_ENABLED:
        return False
    return (chat_id or DEFAULT_COPILOT_CHAT_ID) == DEFAULT_COPILOT_CHAT_ID


async def _append(
    text: str,
    *,
    role: str,
    response_category: ResponseCategory = ResponseCategory.COPILOT,
) -> None:
    """Append one row to this project's v2 thread, swallowing any failure.

    Best-effort like the runtime's own persist hook: the message has already
    streamed, so failing to save it must not break the job the user is watching.
    """
    thread_id = copilot_v2_thread_id()
    if thread_id is None:
        structlogger.debug("copilot_v2.thread_history.no_thread_id", role=role)
        return

    try:
        row = _build_row(text, role=role, response_category=response_category)
        await open_copilot_v2_thread_store().append_messages(thread_id, [row])
        structlogger.debug(
            "copilot_v2.thread_history.persisted",
            thread_id=thread_id,
            role=role,
        )
    except Exception as exc:
        structlogger.warning(
            "copilot_v2.thread_history.persist_failed",
            thread_id=thread_id,
            role=role,
            error=str(exc),
        )


def _build_row(
    text: str, *, role: str, response_category: ResponseCategory
) -> dict[str, Any]:
    """Build the AG-UI row for the message, in the runtime's own shape."""
    from rasa.builder.copilot.pydantic_ai.persisted_messages import (
        assistant_text_row,
        user_row,
    )

    if role == ROLE_USER:
        return user_row(text)
    return assistant_text_row(text, response_category=response_category.value)
